package com.seaoftales.identity.entity;
import com.seaoftales.identity.enums.OtpPurpose; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="email_otps", indexes=@Index(name="ix_otp_context",columnList="email,purpose")) public class EmailOtp { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String email; @Enumerated(EnumType.STRING) @Column(nullable=false) private OtpPurpose purpose; @Column(nullable=false,length=128) private String codeHash; @Column(nullable=false) private Instant expiresAt; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private int attempts; @Column(nullable=false) private boolean used; public Long getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public OtpPurpose getPurpose(){return purpose;} public void setPurpose(OtpPurpose v){purpose=v;} public String getCodeHash(){return codeHash;} public void setCodeHash(String v){codeHash=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public int getAttempts(){return attempts;} public void setAttempts(int v){attempts=v;} public boolean isUsed(){return used;} public void setUsed(boolean v){used=v;} }
